export const CHEMKIN_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/chemkin-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getChemkinStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(CHEMKIN_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
